// XLWebEngineUI: static compiler initialization is lazy and thread-safe.
// No DllMain, ELF constructor, or replacement global allocator in the SDK.
HRESULT xl_dxc_initialize() {
  struct Session {
    HRESULT result;
    Session() : result(InitMaybeFail()) {}
    ~Session() {
      if (FAILED(result)) return;
      DxcSetThreadMallocToDefault();
      ::hlsl::options::cleanupHlslOptTable();
      ::llvm::sys::fs::CleanupPerThreadFileSystem();
      ::llvm::llvm_shutdown();
      DxcClearThreadMalloc();
      DxcCleanupThreadMalloc();
    }
  };
  static Session session;
  return session.result;
}

if (ppv == nullptr) {
